specimens.css:
/* 状态模拟：折叠轨道悬停时真实规则为 .collapsed .toggle:hover .panelIcon { display: inline } 与
   .collapsed .toggle:hover .railMark { display: none }（SidebarRoot.module.css），
   静态快照无法触发 :hover，按同样效果搬到 forceHover 上。 */
.toggle.forceHover .panelIcon { display: inline; }
.toggle.forceHover .railMark { display: none; }

/* 静态快照：Modal 的 .root 由 createPortal 挂在 body 上、position: fixed 铺满视口；
   这里拉回文档流并保留 relative 作为 .mask 的包含块，尺寸与配色仍走真实样式。 */
.root.snapshotStatic { position: relative; inset: auto; }

/* 静态快照：横幅真实由 Toast 用 createPortal 挂到 body，position: fixed 居中并在 3s 后开始 1s 淡出；
   这里把定位拉回文档流、停掉动画，让快照停在可见态，尺寸与配色仍走真实样式。 */
.toast.snapshotStatic { position: relative; inset: auto; transform: none; margin: 0 auto; animation: none; }
